from typing import List

class Solution:
    def smallestUniqueSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        for L in range(1, n + 1):
            cnt = {}
            for i in range(n - L + 1):
                key = tuple(nums[i:i + L])
                cnt[key] = cnt.get(key, 0) + 1
            if any(v == 1 for v in cnt.values()):
                return L
        return n

