using namespace std;

class Solution {
public:
    int smallestUniqueSubarray(vector<int>& nums) {
        int n = nums.size();
        for (int L = 1; L <= n; L++) {
            unordered_map<string, int> cnt;
            for (int i = 0; i + L <= n; i++)
                cnt[string(nums.begin() + i, nums.begin() + i + L)]++;
            bool ok = false;
            for (auto& p : cnt) if (p.second == 1) { ok = true; break; }
            if (ok) return L;
        }
        return n;
    }
};

