        int n = nums.length;
        for (int L = 1; L <= n; L++) {
            Map<String, Integer> cnt = new HashMap<>();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i + L <= n; i++) {
                sb.setLength(0);
                for (int j = i; j < i + L; j++) sb.append(nums[j]).append(',');
                cnt.merge(sb.toString(), 1, Integer::sum);
            }
            boolean ok = false;
            for (int v : cnt.values()) if (v == 1) { ok = true; break; }
            if (ok) return L;
        }
        return n;
    }
}

