from typing import List

class Solution:
    def smallestUniqueSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        M1, M2 = (1 << 61) - 1, (1 << 31) - 1
        B1, B2 = 131, 137

        def feasible(L):
            cnt = {}
            h1 = h2 = 0
            p1 = pow(B1, L - 1, M1)
            p2 = pow(B2, L - 1, M2)
            for i, x in enumerate(nums):
                h1 = (h1 * B1 + x) % M1
                h2 = (h2 * B2 + x) % M2
                if i >= L:
                    h1 = (h1 - nums[i - L] * p1) % M1
                    h2 = (h2 - nums[i - L] * p2) % M2
                if i >= L - 1:
                    k = (h1 << 32) ^ h2
                    cnt[k] = cnt.get(k, 0) + 1
            return any(v == 1 for v in cnt.values())

        lo, hi = 1, n
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

