#include <vector>
#include <unordered_map>
using namespace std;
typedef long long ll;
typedef unsigned long long ull;

const ll M1 = 1000000007LL, M2 = 998244353LL;
const ll B1 = 131, B2 = 137;

ll pw(ll b, ll e, ll m) {
    ll r = 1; b %= m;
    while (e) { if (e & 1) r = (__int128)r * b % m; b = (__int128)b * b % m; e >>= 1; }
    return r;
}

class Solution {
public:
    bool feasible(vector<int>& nums, int L,
                  unordered_map<ull, int>& cnt) {
        cnt.clear();
        ll h1 = 0, h2 = 0;
        ll p1 = pw(B1, L - 1, M1), p2 = pw(B2, L - 1, M2);
        int n = nums.size();
        for (int i = 0; i < n; i++) {
            h1 = (h1 * B1 + nums[i]) % M1;
            h2 = (h2 * B2 + nums[i]) % M2;
            if (i >= L) {
                h1 = ((h1 - nums[i - L] * p1) % M1 + M1) % M1;
                h2 = ((h2 - nums[i - L] * p2) % M2 + M2) % M2;
            }
            if (i >= L - 1) cnt[((ull)h1 << 32) | (ull)(unsigned)h2]++;
        }
        for (auto& p : cnt) if (p.second == 1) return true;
        return false;
    }

    int smallestUniqueSubarray(vector<int>& nums) {
        int n = nums.size(), lo = 1, hi = n;
        unordered_map<ull, int> cnt;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (feasible(nums, mid, cnt)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
};

