import java.util.*;

class Solution {
    static final long M1 = 1000000007L, M2 = 998244353L;
    static final long B1 = 131, B2 = 137;

    private long pw(long b, long e, long m) {
        long r = 1; b %= m;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % m;
            b = b * b % m;
            e >>= 1;
        }
        return r;
    }

    private boolean feasible(int[] nums, int L, Map<Long, Integer> cnt) {
        cnt.clear();
        long h1 = 0, h2 = 0;
        long p1 = pw(B1, L - 1, M1), p2 = pw(B2, L - 1, M2);
        int n = nums.length;
        for (int i = 0; i < n; i++) {
            h1 = (h1 * B1 + nums[i]) % M1;
            h2 = (h2 * B2 + nums[i]) % M2;
            if (i >= L) {
                h1 = ((h1 - nums[i - L] * p1) % M1 + M1) % M1;
                h2 = ((h2 - nums[i - L] * p2) % M2 + M2) % M2;
            }
            if (i >= L - 1) cnt.put(h1 * 2000000011L + h2, cnt.getOrDefault(h1 * 2000000011L + h2, 0) + 1);
        }
        for (int v : cnt.values()) if (v == 1) return true;
        return false;
    }

    public int smallestUniqueSubarray(int[] nums) {
        int n = nums.length, lo = 1, hi = n;
        Map<Long, Integer> cnt = new HashMap<>();
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (feasible(nums, mid, cnt)) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

